// Validate checks the schema and references in a YAML configuration file.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil { return err }
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil { return err }

	var issues []error
	for _, e := range cueerrors.Errors(v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))) {
		issue := Error{Message: e.Error(), Location: Location{File: file}}
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
		}
		issues = append(issues, issue)
	}

	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil { return err }
	issues = append(issues, referenceErrors(file, &root)...)
	if len(issues) == 0 { return nil }
	return errors.Join(append([]error{ErrValidationFailed}, issues...)...)
}

func field(n *yamlv3.Node, key string) *yamlv3.Node {
	if n == nil || n.Kind != yamlv3.MappingNode { return nil }
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key { return n.Content[i+1] }
	}
	return nil
}

func sequence(n *yamlv3.Node) []*yamlv3.Node {
	if n != nil && n.Kind == yamlv3.SequenceNode { return n.Content }
	return nil
}

func referenceErrors(file string, root *yamlv3.Node) []error {
	if root.Kind == yamlv3.DocumentNode && len(root.Content) > 0 { root = root.Content[0] }
	namespace := "default"
	if n := field(root, "namespace"); n != nil && n.Value != "" { namespace = n.Value }
	segments := map[string]bool{}
	for _, s := range sequence(field(root, "segments")) {
		if key := field(s, "key"); key != nil { segments[key.Value] = true }
	}
	var issues []error
	for _, flag := range sequence(field(root, "flags")) {
		key := field(flag, "key")
		if key == nil { continue }
		variants := map[string]bool{}
		for _, variant := range sequence(field(flag, "variants")) {
			if k := field(variant, "key"); k != nil { variants[k.Value] = true }
		}
		for i, rule := range sequence(field(flag, "rules")) {
			add := func(kind string, n *yamlv3.Node) {
				if n == nil || n.Kind != yamlv3.ScalarNode { return }
				known := segments[n.Value]
				if kind == "variant" { known = variants[n.Value] }
				if !known {
					issues = append(issues, Error{
						Message: fmt.Sprintf("flag %s/%s rule %d references unknown %s %q", namespace, key.Value, i+1, kind, n.Value),
						Location: Location{File: file, Line: n.Line, Column: n.Column},
					})
