			segment := field(rule, "segment")
			if segment != nil && segment.Kind == yamlv3.ScalarNode { add("segment", segment) }
			for _, n := range sequence(field(segment, "keys")) { add("segment", n) }
			for _, dist := range sequence(field(rule, "distributions")) { add("variant", field(dist, "variant")) }
		}
	}
	return issues
}
