/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('internal/ext/importer.go')
s=p.read_text()
pos=s.index('\\n\\t// check if document namespace matches')
s=s[:pos]+'''
 if err := validateReferences(doc); err "'!= nil { return err }
'"'''+s[pos:]
s += '''
// validateReferences runs before any writes so bad references cannot leave a partial import.
func validateReferences(doc *Document) error {
 segments := map[string]bool{}
 for _, segment := range doc.Segments {
  if segment "'!= nil { segments[segment.Key] = true }
 }
 namespace := doc.Namespace
 if namespace == "" { namespace = flipt.DefaultNamespace }
 for _, flag := range doc.Flags {
  if flag == nil { continue }
  variants := map[string]bool{}
  for _, variant := range flag.Variants {
   if variant != nil { variants[variant.Key] = true }
  }
  for i, rule := range flag.Rules {
   if rule == nil { continue }
   var keys []string
   if rule.Segment != nil {
    switch segment := rule.Segment.IsSegment.(type) {
    case SegmentKey: keys = []string{string(segment)}
    case *Segments: keys = segment.Keys
    }
   }
   for _, key := range keys {
    if !segments[key] { return fmt.Errorf("flag %s/%s rule %d references unknown segment %q", namespace, flag.Key, i+1, key) }
   }
   for _, distribution := range rule.Distributions {
    if distribution != nil && !variants[distribution.VariantKey] {
     return fmt.Errorf("flag %s/%s rule %d references unknown variant %q", namespace, flag.Key, i+1, distribution.VariantKey)
    }
   }
  }
 }
 return nil
}
'"'''
p.write_text(s)
